import{z as i,x as l,o as A,c as C,q as t,j as s,D as e,d as B,s as o,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"实时操作系统 RTOS","description":"","frontmatter":{"title":"实时操作系统 RTOS","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/emb-rtos.md","filePath":"cs/emb-rtos.md","lastUpdated":1791063341000}'),d={name:"cs/emb-rtos.md"};function m(p,E,D,c,F,h){const r=l("Mermaid");return A(),C("div",null,[E[2]||(E[2]=t('<h1 id="实时操作系统-rtos" tabindex="-1">实时操作系统 RTOS <a class="header-anchor" href="#实时操作系统-rtos" aria-label="Permalink to &quot;实时操作系统 RTOS&quot;">​</a></h1><div class="epigraph"><p>实时不等于快，等于按时：系统的正确性系于截止期，超时的答案和错误的答案同罪。调度器卖的就是这份「最坏情况也来得及」。</p><footer>—— 据 Liu and Layland, JACM 1973；Barry, Mastering the FreeRTOS Real Time Kernel 整理</footer></div><p><a href="/cs/emb-i2c-spi">上一课</a>把传感器与存储器接上了总线，事件经中断进来、工作推迟到主循环。事件一多，主循环就退化成一长串「if 标志就处理」：哪个先处理由代码书写顺序决定，和哪个事件更紧急无关；一个偶发事件插进来，所有周期任务的时序都跟着漂。缺口是把「谁先跑」从书写顺序改成<strong>按截止期仲裁的调度器</strong>。主干课的<a href="/cs/realtime-sched">实时调度对照</a>、<a href="/cs/rate-monotonic">速率单调</a>与 <a href="/cs/edf-sched">EDF</a>已把算法与利用率界限讲清；本课写它们在几 KB 内存的 MCU 上落成什么样的内核，以及中断与任务两条优先级线怎么对表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>裸机主循环的正确性靠「循环足够快」这个隐式假设撑着。任务加到五六个，假设开始漏：串口解析块了，电机控制就晚一拍；晚一拍在示波器上是一格相移，在产品里是抖动和啸叫。缺口不是代码风格，而是<strong>时序耦合无法局部推理</strong>：改任何一处延时，都要在脑子里重跑全部路径。RTOS 把每段工作包成有独立栈的任务，给内核一张任务表，由抢占式调度保证高优先级事件总是先被处理——于是「最坏响应时间」变成可以按利用率与关中断窗口推算的账，而不是猜。</p><p><span class="marginnote">上下文切换可以想象成舞台换演员：把当前任务的寄存器与程序计数器整套收进它自己的栈，再从另一个任务的栈里恢复出一套接着跑。MCU 上一次只要几微秒，但它不是免费的——切换太频繁，省下的等待时间又赔给了换场。</span></p><h3 id="内核只有四件事" tabindex="-1">内核只有四件事 <a class="header-anchor" href="#内核只有四件事" aria-label="Permalink to &quot;内核只有四件事&quot;">​</a></h3><p>MCU 上的 RTOS 核心极小，抓四个部件就够。时钟节拍：SysTick 周期中断驱动延时与超时。上下文切换：每个任务有独立栈，PendSV（配成最低优先级）统一保存与恢复寄存器。抢占式固定优先级调度：就绪的最高优先级者运行，同级可配时间片。阻塞式通信：任务等队列、等信号量时干脆不参与调度，把 CPU 让给就绪者——这一条把「等待」从烧循环变成零成本。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地按三步。第一步划任务：每个任务一个「频率域」，周期与最坏执行时间 \\((C, P)\\) 写在设计文档里，按 <a href="/cs/rate-monotonic">速率单调</a>的口径「周期越短优先级越高」指派；\\(n\\) 个任务利用率 \\(\\sum C_i/P_i\\) 不超过 \\(n(2^{1/n}-1)\\) 才有静态优先级的可调度保证。第二步接中断：<a href="/cs/emb-interrupt-practice">中断实践</a>的「能推迟都推迟」在这里兑现成 <code>FromISR</code> 接口——ISR 只投队列或给信号量，唤醒哪一级任务由内核裁决，中断优先级与任务优先级是两套坐标系，混用是新手事故第一名。第三步处理锁：共享外设要互斥，但<a href="/cs/priority-inversion">优先级反转</a>的教训必须兑现成带继承的互斥量，而不是普通信号量。</p><p><span class="marginnote">利用率代入一组数：任务甲周期 1 ms、执行 0.3 ms，占 0.3；任务乙周期 10 ms、执行 2 ms，占 0.2；合计 0.5，低于三个任务的界限 0.78，静态优先级下可调度。若甲的执行涨到 0.8 ms，总和逼近 1，就得合并任务或重排周期。</span></p><p><span class="marginnote">初学者最容易把 NVIC 的中断优先级与 RTOS 的任务优先级当成一张表；它们是两套坐标系——任何中断都高于任何任务，而 ISR 里必须用 FromISR 专有接口。用错接口轻则断言失败，重则内核链表被撕坏，故障点还远在别处。</span></p>',12)),(A(),s(n,null,{default:e(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISR%5B%22ISR%EF%BC%9A%E5%8F%AA%E6%8A%95%E9%80%92%EF%BC%8C%E4%B8%8D%E5%8A%A0%E5%B7%A5%22%5D%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%E6%88%96%E4%BF%A1%E5%8F%B7%E9%87%8F%22%5D%0A%20%20Q%20--%3E%20WAKE%5B%22%E5%86%85%E6%A0%B8%E8%A7%A3%E9%99%A4%E9%98%BB%E5%A1%9E%EF%BC%8C%E7%BD%AE%E5%B0%B1%E7%BB%AA%E4%BD%8D%22%5D%0A%20%20WAKE%20--%3E%20SCHED%5B%22%E6%8A%A2%E5%8D%A0%E5%BC%8F%E8%B0%83%E5%BA%A6%EF%BC%9A%E6%9C%80%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E5%B0%B1%E7%BB%AA%E8%80%85%E8%BF%90%E8%A1%8C%22%5D%0A%20%20SCHED%20--%3E%20T1%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%EF%BC%9A%E7%94%B5%E6%9C%BA%E6%8E%A7%E5%88%B6%EF%BC%8C%E5%91%A8%E6%9C%9F%201%20ms%22%5D%0A%20%20SCHED%20--%3E%20T2%5B%22%E4%B8%AD%E4%BC%98%E5%85%88%E7%BA%A7%EF%BC%9A%E4%BC%A0%E6%84%9F%E5%99%A8%E9%87%87%E6%A0%B7%EF%BC%8C%E5%91%A8%E6%9C%9F%2010%20ms%22%5D%0A%20%20SCHED%20--%3E%20T3%5B%22%E4%BD%8E%E4%BC%98%E5%85%88%E7%BA%A7%EF%BC%9A%E6%97%A5%E5%BF%97%E4%B8%8E%E4%B8%8A%E6%8A%A5%EF%BC%8C%E5%8F%AF%E6%8E%A8%E8%BF%9F%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"RM 的利用率界限随任务数下降：\\(n=3\\) 时 \\(3(2^{1/3}-1)\\approx 0.780\\)，\\(n\\to\\infty\\) 时趋于 \\(\\ln 2\\approx 0.693\\)。这是充分不必要条件——界限之内必可调度，之外仍可能可行；把它当「不可调度」的判决书会错杀可行任务集。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[B("上下文切换的机制值回票价的地方在"),a("strong",null,"栈预算"),B("：每个任务的栈都要按最坏调用深度加中断嵌套预留，配小了不报编译错，只在运行中践踏相邻任务的对象——嵌入式最难查的偶发死机多半来自这里。内核自带的栈高水位检查要常开，上线前把余量压到有账可查。其次，RTOS 的实时性上限由你而不是内核决定：内核的关中断窗口加上你的临界区窗口，才是最坏响应延迟的真实分母；一个关中断去搬屏的驱动，能把任何调度算法的保证撕掉。这延续了"),a("a",{href:"/cs/lock-irq"},"锁与关中断"),B("的账本口径。")],-1)),(A(),s(n,null,{default:e(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOW%5B%22%E4%BD%8E%E4%BC%98%E5%85%88%E7%BA%A7%E4%BB%BB%E5%8A%A1%EF%BC%9A%E6%8C%81%E6%9C%89%E4%BA%92%E6%96%A5%E9%87%8F%22%5D%20--%3E%20MID%5B%22%E4%B8%AD%E4%BC%98%E5%85%88%E7%BA%A7%E4%BB%BB%E5%8A%A1%E5%B0%B1%E7%BB%AA%EF%BC%8C%E6%8A%8A%E5%AE%83%E6%8A%A2%E5%8D%A0%22%5D%0A%20%20MID%20--%3E%20BLOCK%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E7%AD%89%E5%90%8C%E4%B8%80%E6%8A%8A%E9%94%81%EF%BC%8C%E5%8F%AA%E8%83%BD%E5%B9%B2%E7%AD%89%22%5D%0A%20%20BLOCK%20--%3E%20INV%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E8%A2%AB%E4%B8%AD%E4%BC%98%E5%85%88%E7%BA%A7%E9%97%B4%E6%8E%A5%E5%8E%8B%E4%BD%8F%EF%BC%9A%E5%8F%8D%E8%BD%AC%E6%88%90%E7%AB%8B%22%5D%0A%20%20FIX%5B%22%E4%BA%92%E6%96%A5%E9%87%8F%E5%B8%A6%E4%BC%98%E5%85%88%E7%BA%A7%E7%BB%A7%E6%89%BF%22%5D%20--%3E%20BOOST%5B%22%E6%8C%81%E9%94%81%E8%80%85%E4%B8%B4%E6%97%B6%E6%8A%AC%E5%88%B0%E7%AD%89%E9%94%81%E8%80%85%E7%9A%84%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%0A%20%20BOOST%20--%3E%20NORUN%5B%22%E4%B8%AD%E4%BC%98%E5%85%88%E7%BA%A7%E5%86%8D%E4%B9%9F%E6%8A%A2%E4%B8%8D%E5%8A%A8%E5%AE%83%22%5D%0A%20%20NORUN%20--%3E%20REL%5B%22%E9%94%81%E5%B0%BD%E5%BF%AB%E5%BD%92%E8%BF%98%EF%BC%8C%E5%8F%8D%E8%BD%AC%E8%A7%A3%E9%99%A4%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课写的是软实时的工程口径：错过截止期产品质量下降但不毁坏。硬实时——超时即事故、需要 WCET 证明与认证的那一档，靠的除了调度还有编译器与硬件的时序可分析性，超出本课。也不写 Linux 实时化：PREEMPT_RT 打补丁的思路属于通用内核，主干课的实时调度对照已经给过分界。内存与算力边界也钉一下：几 KB RAM 上跑内核要付每个任务独立栈的税，任务划分过细会先把 RAM 花光——四个到八个任务通常是 MCU 上的合理粒度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实时的本义是可按时完成；调度器把最坏响应时间从猜测变成可推算的账。</li><li>任务按周期域划分，RM 指派优先级，利用率界限是充分条件而非判决书。</li><li>ISR 只投递不加工，<code>FromISR</code> 接口与中断优先级是两套坐标系，不可混表。</li><li>互斥必须带优先级继承；每个任务栈要留最坏余量，偶发死机先查栈践踏。</li><li>出处：Liu and Layland, <em>JACM</em>, 1973；Barry, <em>Mastering the FreeRTOS Real Time Kernel</em>；据本栏 rate-monotonic、priority-inversion 两课口径整理。</li></ul>',4))])}const f=i(d,[["render",m]]);export{S as __pageData,f as default};
